def main():
    OUT.parent.mkdir(parents=True, exist_ok=True)
    with OUT.open("w", newline="", encoding="utf-8-sig") as f:
        w = csv.DictWriter(f, fieldnames=["r", "metric", "value", "unit", "as_of", "source", "url", "status", "note"])
        w.writeheader()
        for row in rows:
            v = row["value"]
            row["value"] = round(v, 3) if isinstance(v, float) else v
            w.writerow(row)
    print(f"rows: {len(rows)} -> {OUT}")
    for row in rows:
        if row["status"] == "Х":
            print(f"  {row['metric']}: {row['value']} {row['unit']}")


if __name__ == "__main__":
    main()
